'use strict';
const G=CloudGame,$=id=>document.getElementById(id);
let state=G.fresh(),storageOK=true,migrated=0;
try{const raw=localStorage.getItem(G.KEY);if(raw){migrated=JSON.parse(raw).version<7?JSON.parse(raw).version:0;state=G.load(raw);}}catch{storageOK=false;}
let currentScreen=state.phase==='active'?'play':state.lastRound?'results':'workbench';try{const selected=sessionStorage.getItem('cloud-chaser-screen');if(['play','results','workbench'].includes(selected))currentScreen=selected;}catch{}
let tab='hardware',activeInput=null,lastTime=performance.now(),lastPhase=state.phase,lastPuffCount=state.round.puffs,lastAction=state.action,toastTimer,renderTime=0;
const fmt=(n,d=1)=>{for(const [v,s]of [[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'K']])if(n>=v)return(n/v).toFixed(d)+s;return n.toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d});};
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4000);}
function save(){state.savedAt=Date.now();try{localStorage.setItem(G.KEY,JSON.stringify(state));storageOK=true;$('save-status').textContent='● Progress saved locally';}catch{storageOK=false;$('save-status').textContent='Save unavailable — export in settings';}$('save-note').textContent=storageOK?'Autosaves every 5s.':'Use Export save in settings.';}
const screenCopy={play:['Play','Find your rhythm. Keep your cloud clean.'],results:['Results','Round scores, puff breakdowns and personal bests.'],workbench:['Workbench','Build your setup. Stock up for the next battery.']};
function rememberScreen(){try{sessionStorage.setItem('cloud-chaser-screen',currentScreen);}catch{}}
function applyScreen(){for(const name of Object.keys(screenCopy))$('screen-'+name).hidden=currentScreen!==name;document.querySelectorAll('[data-screen]').forEach(b=>{if(b.id.startsWith('nav-')){if(b.dataset.screen===currentScreen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}});$('screen-title').textContent=screenCopy[currentScreen][0];$('screen-subtitle').textContent=screenCopy[currentScreen][1];document.body.dataset.screen=currentScreen;}
function scrollToScreen(){requestAnimationFrame(()=>$('screen-heading').scrollIntoView({behavior:state.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));}
function selectScreen(name){if(!screenCopy[name]||name===currentScreen)return;interrupt();currentScreen=name;rememberScreen();lastTime=performance.now();render();scrollToScreen();}
function effect(k,st){const next=G.stats({...state,levels:{...state.levels,[k]:state.levels[k]+1}});switch(k){case'wattage':return`${fmt(st.watts,1)} → ${fmt(next.watts,1)} W ceiling (setting unchanged)`;case'airflow':return`${fmt(st.drawCooling)} → ${fmt(next.drawCooling)} heat removed / draw sec`;case'coil':return`${st.ohms.toFixed(2)} Ω · ${fmt(st.surface)}× → ${fmt(next.surface)}× area`;case'wicking':case'viscosity':return`${fmt(st.wickRate)} → ${fmt(next.wickRate)} liquid delivery`;case'cooling':return`${fmt(st.cooling)} → ${fmt(next.cooling)} heat / resting sec`;case'battery':return`${fmt(st.capacity,0)} → ${fmt(next.capacity,0)} energy / round`;case'tank':return`${fmt(st.tank,0)} → ${fmt(next.tank,0)} liquid capacity`;case'density':return`${fmt(st.density,2)}× → ${fmt(next.density,2)}× clouds · +10% liquid use`;case'economy':return`${fmt(st.liquidRate,2)} → ${fmt(next.liquidRate,2)} liquid / sec`;case'thermal':return`${fmt(st.heatRate)} → ${fmt(next.heatRate)} heat / sec`;case'draw':return`${fmt(st.drawStrength,2)}× → ${fmt(next.drawStrength,2)}× draw · ${fmt(st.lungUsage,2)} → ${fmt(next.lungUsage,2)} lung units / sec`;case'lungs':return`${fmt(st.lungCapacity)} → ${fmt(next.lungCapacity)} capacity units`;case'recovery':return`${fmt(st.lungRecovery)} → ${fmt(next.lungRecovery)} units / resting sec`;}}
function renderCards(){renderDevices();const st=G.stats(state),list=$('upgrade-list');list.replaceChildren();if(tab==='tricks'){for(const t of G.tricks){const row=document.createElement('div');row.className='upgrade';row.innerHTML=`<div class="upgrade-icon">${t.icon}</div><div><h3>${t.name}</h3><p>${t.description}</p><div class="effect">+${Math.round(t.bonus*100)}% output · ${fmt(t.at,0)} scored vapor</div></div><span class="tag">${state.run>=t.at?'UNLOCKED':'MILESTONE'}</span>`;list.append(row);}return;}
 for(const [k,u]of Object.entries(G.upgrades).filter(([,u])=>(u.category||'hardware')===tab)){const level=state.levels[k],max=level>=G.levelLimit(state,k),row=document.createElement('div');row.className='upgrade';const name=u.names?u.names[Math.min(6,Math.floor((level-1)/4))]:'';row.innerHTML=`<div class="upgrade-icon">${u.icon}</div><div><h3>${u.name}<span>LV ${String(level).padStart(2,'0')} / ${G.levelLimit(state,k)}</span></h3><p>${name?name+' · ':''}${u.description}</p><div class="effect">${max?(u.category?'Fully upgraded.': 'Device ceiling reached. Explore your next rig.'):effect(k,st)}</div></div><button class="buy" data-buy="${k}" aria-label="Upgrade ${u.name}"></button>`;list.append(row);updateBuy(row.querySelector('button'),k);}}
function updateBuy(b,k){const u=G.upgrades[k],max=state.levels[k]>=G.levelLimit(state,k),locked=state.total<(u.unlock||0);b.disabled=state.phase!=='workshop'||max||locked||state.vapor<G.cost(state,k);b.textContent=max?'✓ At ceiling':locked?`${fmt(u.unlock,0)} total`:`${fmt(G.cost(state,k),0)} mL +`;}
function renderDevices(){const list=$('device-list');list.replaceChildren();for(const [i,d]of G.devices.entries()){const owned=!!state.owned[d.id],selected=state.device===d.id,available=i===0||!!state.owned[G.devices[i-1].id];if(!owned&&!available)continue;const card=document.createElement('article');card.className='device-card'+(selected?' selected':'');card.innerHTML=`<span class="eyebrow">${d.tag}</span><h3>${d.name}</h3><p>${d.description}</p><p class="effect">${owned?'Owned build':'Starts at hardware level '+d.floor} · base hardware ceiling ${d.cap}${d.area>1?' · '+fmt(d.area,2)+'× heating area':''}</p><p class="device-start">${fmt(10*1.42**(d.floor-1))} W starting ceiling · ${fmt(100*1.48**(d.floor-1),0)} energy · ${fmt(40*1.48**(d.floor-1),0)} tank units</p><button class="${selected?'secondary':'primary'}" data-device="${d.id}">${selected?'✓ Equipped':owned?'Equip this device':`Buy & equip · ${d.price.toLocaleString('en-GB')} vapor`}</button>${!owned?'<small>Starts above an evenly upgraded level '+d.floor+' rig. No liquid included.</small>':''}`;const b=card.querySelector('button');b.disabled=selected||state.phase!=='workshop'||(!owned&&state.vapor<d.price);list.append(card);}}
let fitKey='';
