function advance(now=performance.now()){if(now<lastTime)return;const dt=(now-lastTime)/1000;lastTime=now;if(!document.hidden&&currentScreen==='play')G.tick(state,dt);}
function begin(kind,input){if(currentScreen!=='play')return false;advance();if(activeInput)return false;const ok=kind==='draw'?G.beginDraw(state):G.beginRefill(state);if(ok)activeInput={kind,...input};else if(kind==='refill'&&state.stock<=1e-8)toast('Reserve empty. Buy liquid between rounds.');render();return ok;}
function release(minimum=true){advance();if(activeInput){if(activeInput.kind==='draw')G.endDraw(state,'released',minimum);else G.endRefill(state);}activeInput=null;render();save();}
function interrupt(){advance();G.pause(state);activeInput=null;render();save();}
for(const [id,kind]of [['puff','draw'],['refill-button','refill']]){const b=$(id);b.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();if(begin(kind,{pointer:e.pointerId,startY:e.clientY}))b.setPointerCapture(e.pointerId);});b.addEventListener('pointerup',e=>{if(activeInput?.pointer===e.pointerId)release();});for(const n of ['pointercancel','lostpointercapture'])b.addEventListener(n,e=>{if(activeInput?.pointer===e.pointerId)interrupt();});b.addEventListener('click',e=>{if(e.detail===0&&!activeInput&&begin(kind,{assistive:true}))release();});b.addEventListener('contextmenu',e=>e.preventDefault());}
$('wattage-setting').addEventListener('input',e=>{if(G.setWattage(state,Number(e.target.value))){render();save();}});
$('device-list').onclick=e=>{const b=e.target.closest('[data-device]');if(!b)return;const id=b.dataset.device,owned=!!state.owned[id];if(owned?G.selectDevice(state,id):G.buyDevice(state,id)){renderCards();render();save();toast(G.device(state).name+(owned?' equipped.':' purchased and equipped. No progress reset.'));}};
document.addEventListener('keydown',e=>{if(currentScreen!=='play'||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]'))return;if(e.repeat){if(activeInput?.key===e.code)e.preventDefault();return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;let kind;if(e.code==='Space'&&(e.target.tagName!=='BUTTON'||e.target.id==='puff'))kind='draw';if(e.code==='KeyR')kind='refill';if(['Space','Enter'].includes(e.code)&&e.target.id==='refill-button')kind='refill';if(e.code==='Enter'&&e.target.id==='puff')kind='draw';if(kind){e.preventDefault();begin(kind,{key:e.code});}});document.addEventListener('keyup',e=>{if(activeInput?.key===e.code){e.preventDefault();release();}});window.addEventListener('blur',interrupt);document.addEventListener('visibilitychange',()=>{lastTime=performance.now();G.pause(state);activeInput=null;render();save();});window.addEventListener('pagehide',interrupt);
$('buy-liquid').onclick=()=>{if(G.buyLiquid(state)){render();save();toast(`${G.BOTTLE.quantity} liquid units purchased for ${G.BOTTLE.price} vapor.`);}};$('emergency-liquid').onclick=()=>{const added=G.emergency(state);if(added!==false){render();save();toast(`Recovery supplies: +${fmt(added)} liquid units.`);}};
function startNextRound(){interrupt();if(G.startRound(state)){currentScreen='play';rememberScreen();lastPhase=state.phase;lastPuffCount=0;lastTime=performance.now();render();save();scrollToScreen();toast('Battery and lungs restored. Tank topped up from your reserve stock.');}}
$('bench-start-round').onclick=startNextRound;
document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>selectScreen(b.dataset.screen)));

document.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',t===b));renderCards();render();};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')],i=tabs.indexOf(b),next=tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];next.focus();next.click();};});
$('upgrade-list').onclick=e=>{const b=e.target.closest('[data-buy]');if(b&&G.buy(state,b.dataset.buy)){toast(G.upgrades[b.dataset.buy].name+' upgraded for the next round.');renderCards();render();save();}};
function syncMotion(){$('motion').checked=state.reduced;document.documentElement.classList.toggle('reduced-motion',state.reduced);}syncMotion();$('settings-open').onclick=()=>{interrupt();$('settings').showModal();};$('motion').onchange=e=>{state.reduced=e.target.checked;syncMotion();save();};
$('export-save').onclick=()=>{interrupt();const url=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='cloud-chaser-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import-save').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const raw=JSON.parse(await f.text());if(![1,2,3,4,5,6,7].includes(raw.version)||!raw.levels||!Number.isFinite(raw.vapor))throw Error();if(!confirm('Replace your current progress with this save?'))return;interrupt();state=G.load(raw);currentScreen=state.phase==='active'?'play':state.lastRound?'results':'workbench';rememberScreen();activeInput=null;lastPhase=state.phase;lastPuffCount=state.round.puffs;lastTime=performance.now();syncMotion();renderCards();render();save();toast('Devices, supplies and records restored. Existing hardware is preserved.');}catch{toast('That save file could not be read.');}e.target.value='';};
$('reset').onclick=()=>{if(!confirm('Reset all progress and personal bests? This cannot be undone.'))return;state=G.fresh();currentScreen='play';rememberScreen();activeInput=null;lastPhase=state.phase;lastPuffCount=0;syncMotion();renderCards();render();save();$('settings').close();};
function frame(now){advance(now);if(now-renderTime>75||lastPhase!==state.phase||lastPuffCount!==state.round.puffs){render();renderTime=now;}requestAnimationFrame(frame);}setInterval(()=>{if(!document.hidden)save();},5000);renderCards();render();save();requestAnimationFrame(frame);if(migrated)setTimeout(()=>toast('Technique update: draw strength is now an upgrade. Devices, supplies and records are preserved.'),500);if(!storageOK)toast('Storage unavailable. Export your save from Settings.');

